exercise.solution:
CREATE TABLE lab_l07_students (id SERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE lab_l07_courses (id SERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL);

CREATE TABLE lab_l07_enrollments (
  student_id INTEGER NOT NULL REFERENCES lab_l07_students(id),
  course_id  INTEGER NOT NULL REFERENCES lab_l07_courses(id),
  PRIMARY KEY (student_id, course_id)
);

